    static void Bonus()
    {
        ResourceCases();
        foreach(var (c,expected) in new[]{(22,false),(23,false),(24,false),(25,true),(26,false),(27,true)})foreach(int mods in new[]{0,4194304})Add($"B01 count{c} modifier{mods}","E025/E041 C>N+3 signed even remainder N20",()=>Eq(SpinnerSampleSelection.BonusAllowed(c,20,mods),expected&&mods==0));
        foreach(var (c,n,expected) in new[]{(int.MinValue,int.MaxValue,false),(int.MaxValue,int.MaxValue,false),(0,int.MaxValue-1,false),(1,int.MaxValue-1,true),(-1,int.MaxValue-1,true)})Add($"B02 unchecked threshold C{c} N{n}","E041 unchecked N+3 and signed subtraction/remainder artificial",()=>Eq(SpinnerSampleSelection.BonusAllowed(c,n,0),expected));
        Add("B03 suppressed sound retains raw16384","E025 selector unchanged by numeric modifier",()=>{var o=new SpinnerProgressObservation();for(int i=1;i<=24;i++)o.Observe(i,20);int sounds=0;int raw=o.Observe(25,20,bonus:()=>{if(SpinnerSampleSelection.BonusAllowed(o.Count,20,4194304))sounds++;});Eq(raw,16384);Eq(sounds,0);Eq(o.Count,25);});
        foreach(int handle in new[]{-1,0,929})Add("B04 independent player registration sample "+handle,"E041 M3b2b registers before queue;no standard attenuation/pan",()=>{var s=State();var f=new Rig();var sink=new Sink();var order=new List<string>();sink.Enter=_=>order.Add("queue");var p=SpinnerSampleSelection.Bonus(s.Definition,handle,73,Policy,sink,x=>{order.Add("register");Eq(sink.Requests.Count,0);Eq(x.Sample,handle);});Seq(order,"register","queue");Eq(p.InitialVolume,.73f);Eq(p.Restart,true);Eq(p.Secondary,false);var q=sink.Requests.Single();Eq(q.Kind,SoundEventKind.SpinnerBonus);Eq(q.Volume,73);Eq(q.Layer,0);Eq(q.Pan,0f);Eq(q.Factor,1f);Bits(q.Gain,0x3e958106);Yes(ReferenceEquals(q.BonusPlayer,p),"registered player identity");Eq(f.Spin.Channel,733);Eq(f.B.Ops.Count,0);Eq(s.Observation.Count,0);Eq(s.Result,Judgement.Pending);});
        foreach(int handle in new[]{-1,0,929})Add("B05 actual worker sample validity "+handle,"E037/E041 one-shot worker separate validity",()=>{var actions=new Queue<Action>();int played=0;var p=new CircleSoundPlayback(_=>played++,a=>actions.Enqueue(a),()=>{});p.Resume();SpinnerSampleSelection.Bonus(State().Definition,handle,73,Policy,p);Eq(actions.Count,1);while(actions.TryDequeue(out var a))a();Eq(played,handle==929?1:0);});
        Add("B06 no bonus for raw0/4096/8192","E025/E041 ancillary bonus only selector branch",()=>{var o=new SpinnerProgressObservation();int b=0;Seq(Enumerable.Range(1,4).Select(i=>o.Observe(i,20,bonus:()=>b++)),0,8192,4096,8192);Eq(b,0);});
        Add("B07 callback backend failure contained","ENGINEERING one-shot worker optional effects",()=>{var q=new Queue<Action>();var p=new CircleSoundPlayback(_=>throw new IOException("bonus sink"),a=>q.Enqueue(a),()=>{});p.Resume();SpinnerSampleSelection.Bonus(State().Definition,929,73,Policy,p);q.Dequeue()();Eq(p.Error,"bonus sink");});
        Add("B08 registration failure before queue","E041 independent partial boundary",()=>{var sink=new Sink();Throws<IOException>(()=>SpinnerSampleSelection.Bonus(State().Definition,929,73,Policy,sink,_=>throw new IOException("registry")));Eq(sink.Requests.Count,0);});
        Add("B09 current global volume not spinner override","E041 M3b42 versus object sample volume",()=>{var f=new Rig();f.Global.Clock(110);var sink=new Sink();SpinnerSampleSelection.Bonus(Map().Spinners[0],929,f.Global.CurrentVolume,Policy,sink);Eq(sink.Requests.Single().Volume,73);});
